import time
import traceback

from typing import List

from taf.rfrl.csv4all.resources.multinode_operations.threads_runner import ThreadsRunner
from taf.rfrl.csv4all.resources.node.node import Node
from taf.rfrl.csv4all.resources.utilities.decorators import function_wrapper
from taf.rfrl.csv4all.resources.utilities.exceptions import NotAllOperationsSucceed
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class MultiNodeOperations:

    def __init__(self, nodes: List[Node] = None):
        self.nodes = nodes

    class NodeThreadRunner(ThreadsRunner):

        def create_multiple_node_threads(self, nodes: List[Node], function, *args, **kwargs):
            for node in nodes:
                self.create_thread(f"{node.node_alias}", getattr(node, function.__name__), *args,
                                   **kwargs)

    def run_operations_as_threads_and_return(self, nodes: List[Node], function, *args, **kwargs):
        with self.NodeThreadRunner() as runner:
            runner.create_multiple_node_threads(nodes, function, *args, **kwargs)
        return runner.thread_results

    @staticmethod
    def run_operations_in_sequence(nodes: List[Node], function, *args, ignore_error=False, **kwargs):
        results = {"Passed": {}, "Failed": {}, }
        for node in nodes:
            try:
                results["Passed"][node.node_alias] = getattr(node, function.__name__)(*args, **kwargs)
            except Exception as e:
                if ignore_error:
                    test_logger(f"Exception raised on {node.node_alias} during call of {function.__name__}",
                                console=False)
                else:
                    test_logger(f"Exception raised on {node.node_alias} during call of {function.__name__}",
                                log_level="ERROR")
                test_logger(e, console=False)
                test_logger(traceback.format_exc(), log_level="debug", console=False)

                results["Failed"][node.node_alias] = e
        if results["Failed"] and not ignore_error:
            failed_nodes = {node for node in results["Failed"].keys()}
            raise NotAllOperationsSucceed(function, results, failed_nodes)
        return results

    @staticmethod
    def _get_max_timeout(nodes, timer: int = None, timer_type=None):
        if timer or timer == 0:
            return timer
        return max(getattr(node, timer_type) for node in nodes)

    @function_wrapper
    def wait_for_unexpected_alarms(self, timeout: int):
        if timeout:
            minutes = timeout // 60
            seconds = timeout % 60
            sep = ' and' if seconds > 0 else ''
            _minute = "minute" if minutes == 1 else "minutes"
            test_logger(f"Waiting {f'{minutes} {_minute}{sep} ' if minutes > 0 else ''}"
                        f"{f'{seconds} seconds ' if seconds > 0 else ''}for unexpected alarms")
        time.sleep(timeout)

    @function_wrapper
    def start_log_tracing_all_nodes(self):
        self.run_operations_in_sequence(self.nodes, Node.start_trace)

    @function_wrapper
    def stop_log_tracing_and_download_from_all_nodes(self, logs_dir):
        self.run_operations_in_sequence(self.nodes, Node.stop_trace_and_download_logs, logs_dir=logs_dir)

    @function_wrapper
    def start_watching_alarms_on_all_nodes(self, ignore_gps: bool = False):
        self.run_operations_in_sequence(self.nodes, Node.start_watching_alarms, ignore_gps=ignore_gps)

    @function_wrapper
    def stop_watching_alarms_on_all_nodes(self):
        self.run_operations_in_sequence(self.nodes, Node.stop_watching_alarms)

    @function_wrapper
    def stop_logs_and_verify_on_all_nodes(self, logs_dir, affected_node=None,
                                          reset_incrementation_on_active_node=False):
        if affected_node:
            not_affected_nodes = self.nodes.copy()
            not_affected_nodes.remove(affected_node)
            results = self.run_operations_in_sequence(not_affected_nodes, Node.stop_logs_and_verify, logs_dir=logs_dir,
                                                      reset_incrementation=False)
            try:
                results["Passed"][affected_node.node_alias] = \
                    affected_node.stop_logs_and_verify(logs_dir, reset_incrementation_on_active_node)
            except Exception as e:
                results["Failed"][affected_node.node_alias] = e
        else:
            results = self.run_operations_in_sequence(self.nodes, Node.stop_logs_and_verify, logs_dir=logs_dir,
                                                      reset_incrementation=reset_incrementation_on_active_node)
        return {node for node in results["Failed"].keys()}

    @function_wrapper
    def verify_all_nodes(self, hw_timer=None, alarm_timer=None):
        def update_bts_fault_message():
            try:
                for node_alias in state_results["Failed"].keys():
                    node = [node for node in self.nodes if node.node_alias == node_alias][0]
                    exception = state_results['Failed'][node_alias].exception
                    node.btsverify.bts_fault_message += f"\n{exception}"
                    test_logger(f"State verification failed for {node.node_alias}\n{exception}", "ERROR")
            except AttributeError:
                pass

        state_results = self.run_operations_as_threads_and_return(self.nodes, Node.verify_node_bts_state,
                                                                  hw_timer=self._get_max_timeout(self.nodes, hw_timer,
                                                                                                 "hw_timer"))
        if state_results["Failed"]:
            update_bts_fault_message()
            test_logger(f"State verification failed for nodes: {list(state_results['Failed'].keys())}",
                        log_level="ERROR")
        self.wait_for_unexpected_alarms(self._get_max_timeout(self.nodes, alarm_timer, "alarm_timer"))
        alarm_results = self.run_operations_in_sequence(self.nodes, Node.verify_no_unexpected_alarms, ignore_error=True)
        if alarm_results["Failed"]:
            test_logger(f"Alarm check failed for nodes: {list(alarm_results['Failed'].keys())}", log_level="ERROR")
        return {node for node in {*state_results["Failed"].keys(), *alarm_results["Failed"].keys()}}

    @function_wrapper
    def verify_mplane(self):
        mplane_status = self.run_operations_as_threads_and_return(self.nodes, Node.verify_mplane_accessibility)
        if mplane_status["Failed"]:
            test_logger(f"Mplane verification failed for nodes: {list(mplane_status['Failed'].keys())}", "ERROR")
        return {node for node in {*mplane_status["Failed"].keys()}}

    @function_wrapper
    def execute_commands_on_rmods(self):
        self.run_operations_in_sequence(self.nodes, Node.execute_commands_on_rmods)
